(1353, 'Exothermic reaction', 'Réaction exothermique', 'تفاعل طارد للحرارة', 'A reaction that releases heat to the surroundings (ΔH < 0)', 'Réaction libérant de la chaleur vers l''environnement (ΔH < 0)', 'تفاعل يطلق حرارة إلى المحيط (ΔH < 0)', '', '', '', 'Biophysique', 'Thermodynamique', '', '', '', '/ˌɛksoʊˈθɜːrmɪk/'),
(1354, 'Endothermic reaction', 'Réaction endothermique', 'تفاعل ماص للحرارة', 'A reaction that absorbs heat from the surroundings (ΔH > 0)', 'Réaction absorbant de la chaleur de l''environnement (ΔH > 0)', 'تفاعل يمتص حرارة من المحيط (ΔH > 0)', '', '', '', 'Biophysique', 'Thermodynamique', '', '', '', '/ˌɛndoʊˈθɜːrmɪk/'),
